def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into a single dictionary.
    If there are duplicate keys, the values from the later dictionaries
    will overwrite the earlier ones.
    """
    # Combine all three dictionaries into a single dictionary in the given order
    merged_dict = {}
    for d in (dict1, dict2, dict3):
        merged_dict.update(d)
    # Return the merged dictionary (sorting is not required unless explicitly specified)
    return merged_dict

# Example usage and tests:

# Test case 1
assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"}, 
    {"G": "Green", "W": "White"}, 
    {"O": "Orange", "W": "White", "B": "Black"}
) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

# Test case 2
assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"}, 
    {"G": "Green", "W": "White"}, 
    {"L": "lavender", "B": "Blue"}
) == {'B': 'Blue', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'L': 'lavender'}

# Test case 3: All dictionaries are empty
assert merge_dictionaries_three({}, {}, {}) == {}

# Test case 4: One dictionary is empty
assert merge_dictionaries_three({"A": 1}, {}, {"B": 2}) == {"A": 1, "B": 2}

# Test case 5: Non-string keys and values
assert merge_dictionaries_three({1: "one", 2: "two"}, {2: "TWO"}, {3: "three"}) == {1: "one", 2: "TWO", 3: "three"}
